record.field:
# 1. Get the Ticket Record
ticket = record

# 2. Check for Invoice
if not ticket.consultation_invoice_id:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'No Invoice',
            'message': 'No Consultation Invoice is linked to this ticket.',
            'type': 'warning',
            'sticky': False,
        }
    }
else:
    # 3. Generate Print Data from the Invoice
    invoice = ticket.consultation_invoice_id

    # Directly call the method (we know it exists)
    escpos_str = invoice._build_escpos_invoice_at301()

    # 4. Trigger the Print Action
    action = {
        'type': 'ir.actions.client',
        'tag': 'hospital_qz_print',
        'params': {
            'escpos_raw': escpos_str,
            'notification': {
                'type': 'success',
                'title': 'Reprinting',
                'message': 'Consultation Receipt sent to printer.',
                'sticky': False,
            }
        },
    }
